\begin{corollary}[A 3-dimensional solution has $\phi$-almost nonnegative curvature]
\label{cor:chow-ii-appd-almost-nonnegative-curvature}
\source{chow-et-al-ricci-flow-part-ii:page-0392}
\uses{thm:chow-ii-appd-hamilton-ivey}
\dcref{appD:D.19}
\group{Curvature Pinching}


For a closed three-dimensional Ricci flow with
$\lambda_{\min}(\operatorname{Rm})(\cdot,0)\geq-1$,
\[
 \lambda_{\min}(\operatorname{Rm})\geq-\phi(R)R-3e^6,
\]
where $\phi(u)=\psi^{-1}(u)/u$ for $u>3e^6$, $\phi(u)=0$ otherwise, and
$\psi(x)=x(\log x-3)$. The function $\phi$ is bounded and decreasing on
$[3e^6,\infty)$ and tends to zero at infinity.
\end{corollary}

